package com.petlis.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;import com.petlis.common.exception.BusinessException;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyBankRefundLocalDatabaseTest {
 @Autowired FeatureStore store;@Autowired ObjectMapper json;LegacyBankExecutionLocalDatabaseTest payment;LegacyBankRefundService refunds;
 @BeforeEach void setup()throws Exception{payment=new LegacyBankExecutionLocalDatabaseTest();payment.store=store;payment.json=json;payment.setup();var sent=payment.execution.claim(payment.key,"LOCALTEST",false);payment.execution.unknown(payment.key,sent.token());var query=payment.execution.claim(payment.key,"LOCALTEST",true);payment.execution.finish(payment.key,query.token(),true,json.readTree("{\"retCode\":\"00000\",\"tradeStatus\":\"00\",\"oriMerOrdrNo\":\""+sent.orderId()+"\",\"trxTtlAmt\":\"1250\",\"chnlMerOrdrNo\":\"refund-test-channel\"}"));refunds=new LegacyBankRefundService(store,payment.f.access,payment.execution,json);store.jdbc().update("UPDATE lin_operational_config SET config_value=JSON_SET(config_value,'$.refundEnabled',true,'$.refundQueryEnabled',true) WHERE config_key='legacy-bank-payments'");}
 LegacyBankRefundService.Command command(String amount,String key){return new LegacyBankRefundService.Command(payment.key,amount,"本机退款测试",key);}
 @Test void refundIntentIsIdempotentAndCannotOverReserveOriginalPayment(){var first=refunds.create(command("5.00",payment.key+"_1"),"LOCALTEST");assertEquals(first,refunds.create(command("5.00",payment.key+"_1"),"LOCALTEST"));assertEquals("500",first.get("amountFen"));refunds.create(command("7.50",payment.key+"_2"),"LOCALTEST");assertEquals(409,assertThrows(BusinessException.class,()->refunds.create(command("0.01",payment.key+"_3"),"LOCALTEST")).getCode());assertThrows(BusinessException.class,()->refunds.create(command("4.00",payment.key+"_1"),"LOCALTEST"));}
 @Test void uncertainRefundNeverResendsAndQueryUsesOriginalSaleAsPhp(){var key=payment.key+"_refund";refunds.create(command("12.50",key),"LOCALTEST");var sent=refunds.claim(key,"LOCALTEST",false);assertEquals(new java.math.BigInteger("1250"),sent.parameters().get("trxAmt"));assertThrows(BusinessException.class,()->refunds.claim(key,"LOCALTEST",false));refunds.unknown(key,sent.token());assertThrows(BusinessException.class,()->refunds.claim(key,"LOCALTEST",false));var query=refunds.claim(key,"LOCALTEST",true);assertEquals(sent.parameters().get("oriMerOrdrNo"),query.parameters().get("oriMerOrdrNo"));assertFalse(query.parameters().containsKey("trxAmt"));assertThrows(BusinessException.class,()->refunds.claim(key,"LOCALTEST",true));assertThrows(BusinessException.class,()->refunds.cancel(key));}
 @Test void verifiedBankReplyDoesNotInventClinicalOrFundReversal()throws Exception{var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",payment.f.order);var key=payment.key+"_refund";refunds.create(command("12.50",key),"LOCALTEST");var sent=refunds.claim(key,"LOCALTEST",false);refunds.finish(key,sent.token(),json.copy().enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS).readTree("{\"retCode\":\"00000\",\"refundStatus\":\"PROVIDER_SPECIFIC\",\"message\":\"bank reply\",\"decimalValue\":0.1234567890123456789,\"longNumber\":9007199254740993}"));assertEquals("BANK_RESPONSE",refunds.request(key).get("status"));assertTrue(refunds.request(key).get("bankResponseText").toString().contains("0.1234567890123456789"));assertTrue(refunds.request(key).get("bankResponseText").toString().contains("9007199254740993"));assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",payment.f.order));assertEquals(1,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_paylog WHERE TradeNoAli='refund-test-channel' AND TradeNoUser=(SELECT OrderId FROM lin_lb_payordermain WHERE Remark=?)",Integer.class,"订单:"+payment.key));}
 @Test void cancellingUnsentIntentReleasesReservationButDoesNotRecycleRequestKey(){var key=payment.key+"_cancel";refunds.create(command("12.50",key),"LOCALTEST");assertEquals("CANCELLED",refunds.cancel(key).get("status"));assertEquals("CANCELLED",refunds.create(command("12.50",key),"LOCALTEST").get("status"));refunds.create(command("12.50",payment.key+"_new"),"LOCALTEST");}
 @Test void independentGateAndOwnerScopeRemainEffectiveForRefunds(){var key=payment.key+"_scope";refunds.create(command("1.00",key),"LOCALTEST");store.jdbc().update("UPDATE lin_operational_config SET config_value=JSON_SET(config_value,'$.refundEnabled',false) WHERE config_key='legacy-bank-payments'");assertEquals(409,assertThrows(BusinessException.class,()->refunds.create(command("1.00",payment.key+"_disabled"),"LOCALTEST")).getCode());assertEquals("READY",refunds.request(key).get("status"));var original=payment.f.access.current();org.mockito.Mockito.when(payment.f.access.current()).thenReturn(new com.petlis.common.security.CurrentActor(original.userId()+1000000,original.roles(),Set.of(),Set.of(),original.dataScope()));assertEquals(404,assertThrows(BusinessException.class,()->refunds.request(key)).getCode());assertEquals(0L,refunds.list(0,20).get("total"));}
}
